function CreatePlayer:__init()
    self.controller = nil
end


function CreatePlayer:__delete()
    self.co_1 = nil
    self.emptyFunc = nil
end



function CreatePlayer:Init( playerParams_ )
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(function()
        self:_DelayInit( playerParams_ )
    end) 
end

--function CreatePlayer:_DelayInit( humanRootTF_, humanAnimatorTF_, playerParams_ )
function CreatePlayer:_DelayInit( playerParams_ )
    KTool.SetActive(self.controller.gameObject, true)


    -- todo: 未来要支持 单独猫 / 单独人 模式:
    self.isSupportHuman = isNotNull(playerParams_.humanRootTF)
    self.isSupportCat = true 
    


    -- 得到 人猫初始形态:
    self.initMorphologyType = playerParams_.initMorphologyType


    assert(   self.switchablePlayerControllerBH
        and self.virtualTargetControllerTF and self.vcamControllerTF and self.viewRotateControllerBH and self.roleMorphologyVolumeManager
        )

    self.switchablePlayerController = DreamSpaceLuaUtils.GetLuaScr(self.switchablePlayerControllerBH.gameObject, "Game.DreamSpace.CharacterController.SwitchablePlayerController" )
    assert( self.switchablePlayerController )


    self.viewRotateController = DreamSpaceLuaUtils.GetLuaScr(self.viewRotateControllerBH.gameObject, "Game.DreamSpace.CharacterController.ViewRotateController" )
    assert( self.viewRotateController )

    self.playerInputSwitcher = DreamSpaceLuaUtils.GetLuaScr(self.playerInputTF.gameObject, "Game.DreamSpace.CharacterController.PlayerInputSwitcher" )
    assert( self.playerInputSwitcher )

    self.playerInputSwitcher:Init( playerParams_.isUseManualViwRotateInPCMode, playerParams_.isHideLeftJoystick )

    ---
    local vTargetFollow      = self.virtualTargetControllerTF:Find("Follow")
    local vTargetLookAt2      = self.virtualTargetControllerTF:Find("LookAt2")
    local vTargetDelayFollowTF = self.virtualTargetControllerTF:Find("DelayFollow")
    local vCam3rdPersonFollowTF  = self.vcamControllerTF:Find("VCam3rdPersonFollow")
    assert(vTargetFollow and vTargetDelayFollowTF )

    

    -- ====================================== Human ============================================
    local humanHeadTF = nil
    if self.isSupportHuman == true then 

        self.humanCharacter = KTool.GetComponent(playerParams_.humanRootTF.gameObject, typeof(Character))

        assert( self.humanCharacter and self.humanControllerBH and self.humanFootStepBH )

        if playerParams_.isUsePiecesCollector == true then 
            AddLuaBehaviour(self.humanCharacter.gameObject, "Game.DreamSpace.PiecesCollection.PiecesCollector")
        end 
    
        self.humanController = DreamSpaceLuaUtils.GetLuaScr(self.humanControllerBH.gameObject, "Game.DreamSpace.CharacterController.PlayerController" )
        assert( self.humanController )

        self.humanFootStep = DreamSpaceLuaUtils.GetLuaScr(self.humanFootStepBH.gameObject, "Game.DreamSpace.CharacterController.HumanFootStep" )
        assert( self.humanFootStep )
        self.humanFootStep:Init( vTargetFollow, playerParams_.isHideFootStep )

        ------ 
        self.humanController:Init(
            self.humanCharacter,
            playerParams_.humanAnimatorTF,
            {
            function( currentFootStepState_, oldFootStepState_ )
                self.humanFootStep:WhenPlayerMoveStateChanged( currentFootStepState_, oldFootStepState_ )
            end
            }
        )
        self.humanController:SetCharacterFSM()

        if playerParams_.isIgnoreRunStop == true then 
            self.humanController.hasRunStop = false
        end

        if playerParams_.isIgnoreHuman180TurnBack == true then 
            self.humanController.hasTurnBack = false
        end

        self.humanFollow = self.humanCharacter.transform


        ---- 
        -- 内嵌一个接近 human 头部高度的节点:
        local humanHead = GameObject("HumanHead")
        KTool.SetParent( humanHead, vTargetFollow.gameObject, false )
        humanHeadTF = humanHead.transform
        humanHeadTF.localPosition = Vector3( 0, playerParams_.initHumanScale.y * 1.6, 0 ) -- todo: 假定人物身高 1.6
        humanHeadTF.rotation = Quaternion.identity
        humanHeadTF.localScale = Vector3.one
    end

    -- ====================================== Cat ============================================
    if self.isSupportCat == true then 

        assert( self.catCharacter and self.catControllerBH and self.catFootStepBH )

        if playerParams_.isUsePiecesCollector == true then 
            AddLuaBehaviour(self.catCharacter.gameObject, "Game.DreamSpace.PiecesCollection.PiecesCollector")
        end 

        self.catController = DreamSpaceLuaUtils.GetLuaScr(self.catControllerBH.gameObject, "Game.DreamSpace.CharacterController.PlayerControllerQuadruped" )
        assert( self.catController )

        if self.JumpHintBH then
            self.jumpHint = DreamSpaceLuaUtils.GetLuaScr(self.JumpHintBH.gameObject, "Game.DreamSpace.Hint.JumpHint" )
        end

        self.catFootStep = DreamSpaceLuaUtils.GetLuaScr(self.catFootStepBH.gameObject, "Game.DreamSpace.CharacterController.CatFootStep" )
        assert( self.catFootStep )
        self.catFootStep:Init( vTargetFollow, playerParams_.isHideFootStep )

        ------ 
        self.catController:Init(
            self.catCharacter,
            playerParams_.isIgnoreJumpHint==true,
            {
            function( currentFootStepState_, oldFootStepState_ )
                self.catFootStep:WhenPlayerMoveStateChanged( currentFootStepState_, oldFootStepState_ )
            end
            }
        )
        self.catController:SetCharacterFSM()

        self.catFollow = self.catCharacter.transform
        

    end

    -- ============================

    
    self.switchablePlayerController:Init( 
        self.humanCharacter,    -- 允许为 nil
        self.humanController,   -- 允许为 nil
        self.catCharacter, self.catController, self.initMorphologyType, playerParams_.initRoleDir 
    )


    self.emptyFunc = function()   end  -- 一个空函数
    self.roleMorphologyVolumeManager.OpenEffect = self.emptyFunc
    self.roleMorphologyVolumeManager.CloseEffect = self.emptyFunc
    
    self.roleMorphologyVolumeManager.IntoCatVolume = function()
        self.switchablePlayerController:IntoCatVolume()
    end
    
    self.roleMorphologyVolumeManager.IntoHumanVolume = function()
        self.switchablePlayerController:IntoHumanVolume()
    end
    
    self.roleMorphologyVolumeManager.LeaveAnyVolume = function()
        self.switchablePlayerController:LeaveAnyVolume()
    end
    self.roleMorphologyVolumeManager:Init()

    -------------
    

    if self.jumpHint then
        self.jumpHint.JumpUp = function()
            self.switchablePlayerController:JumpUp()
        end
        self.jumpHint.JumpDown = function()
            self.switchablePlayerController:JumpDown()
        end
        self.jumpHint.JumpForward = function()
            self.switchablePlayerController:JumpForward()
        end
        self.jumpHint:Init( playerParams_.isIgnoreJumpHint==true )
    end

    ---------


    self.virtualTargetsController = DreamSpaceLuaUtils.GetLuaScr(self.virtualTargetControllerTF.gameObject, "Game.DreamSpace.CharacterController.VirtualTargetsController" )
    assert( self.virtualTargetsController )

    self.virtualTargetsController:Init(self.humanFollow, self.catFollow, self.initMorphologyType)


    ---- 
    self.vcam3rdPersonFollowControllerEnv = DreamSpaceLuaUtils.GetLuaScr(self.vcamControllerTF.gameObject, "Game.DreamSpace.CharacterController.VCam3rdPersonFollowController" )
    assert( self.vcam3rdPersonFollowControllerEnv )
    self.vcam3rdPersonFollowControllerEnv:Init( self.initMorphologyType, playerParams_ )



    self.switchablePlayerController:SetVTargetFollow( vTargetFollow )

    local vTargetDelayFollowBH = KTool.GetComponent(vTargetDelayFollowTF.gameObject, typeof(LuaBehaviour))
    assert( vTargetDelayFollowBH )


    assert( vCam3rdPersonFollowTF )
    local vCam3rdPersonFollowComp = KTool.GetComponent(vCam3rdPersonFollowTF.gameObject, typeof(CinemachineVirtualCamera))
    assert( vCam3rdPersonFollowComp )

    vCam3rdPersonFollowComp.Priority = 101 -- todo: debug: 抢占 vcam 优先权



    if self.isSupportHuman == true then 
        GlobalsInDreamSpace.SetComponent("vTargetHumanHead", humanHeadTF)
    end

    GlobalsInDreamSpace.SetComponent("vTargetFollow", vTargetFollow)
    GlobalsInDreamSpace.SetComponent("vTargetLookAt2", vTargetLookAt2)
    GlobalsInDreamSpace.SetComponent("vTargetDelayFollowBH", vTargetDelayFollowBH)
    GlobalsInDreamSpace.SetComponent("vcamControllerTF", self.vcamControllerTF)   
    GlobalsInDreamSpace.SetComponent("vcam3rdPersonFollow", vCam3rdPersonFollowComp)    -- 新相机
    GlobalsInDreamSpace.SetComponent("switchablePlayerControllerBH", self.switchablePlayerControllerBH)
    GlobalsInDreamSpace.SetComponent("roleMorphologyVolumeManager", self.roleMorphologyVolumeManager)
    GlobalsInDreamSpace.SetComponent("viewRotateControllerBH", self.viewRotateControllerBH)

    if self.isSupportHuman == true then 
        GlobalsInDreamSpace.SetComponent("humanControllerBH", self.humanControllerBH)
        GlobalsInDreamSpace.SetComponent("humanCharacter", self.humanCharacter)
    end 

    if self.isSupportCat == true then 
        GlobalsInDreamSpace.SetComponent("catControllerBH", self.catControllerBH)
        GlobalsInDreamSpace.SetComponent("catCharacter", self.catCharacter)
    end 




    -- 相机旋转管理器:
    self.viewRotateController:Init(self.initMorphologyType, playerParams_.pitchMinDegree, playerParams_.pitchMaxDegree, playerParams_.isUseManualViwRotateInPCMode )


    ---@type DreamSpaceStates
    local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
    Events.Broadcast(DreamSpaceStates.EventNames.OnCreatePlayerInitEnd, nil)
    DreamSpaceStates.isRoleControllerInited = true
end




function CreatePlayer:OnDestroy()

    --printError("CreatePlayer:OnDestroy")

    ---@type DreamSpaceStates
    local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
    Events.Broadcast(DreamSpaceStates.EventNames.OnCreatePlayerDestroy, nil)
    DreamSpaceStates.isRoleControllerInited = false

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象

    GlobalsInDreamSpace.RemoveComponent( "vTargetFollow" )
    GlobalsInDreamSpace.RemoveComponent( "vTargetLookAt2" )
    GlobalsInDreamSpace.RemoveComponent( "vTargetDelayFollowBH" )
    GlobalsInDreamSpace.RemoveComponent( "vcamControllerTF" )
    GlobalsInDreamSpace.RemoveComponent( "vcam3rdPersonFollow" )
    GlobalsInDreamSpace.RemoveComponent( "switchablePlayerControllerBH" )
    GlobalsInDreamSpace.RemoveComponent( "roleMorphologyVolumeManager" )
    GlobalsInDreamSpace.RemoveComponent( "viewRotateControllerBH" )

    if self.isSupportHuman == true then 
        GlobalsInDreamSpace.RemoveComponent( "humanControllerBH" )
        GlobalsInDreamSpace.RemoveComponent( "humanCharacter" )
        GlobalsInDreamSpace.RemoveComponent( "vTargetHumanHead" )
    end 

    if self.isSupportCat == true then 
        GlobalsInDreamSpace.RemoveComponent( "catControllerBH" )
        GlobalsInDreamSpace.RemoveComponent( "catCharacter"  )
    end 



    self:Delete()
end

-- =========================================== Self ================================================ --







return CreatePlayer